'use strict';
const M=Spectral,$=id=>document.getElementById(id),TAU=Math.PI*2;
const state={level:0,tab:'puzzle',method:'tikhonov',T:.025,eps:.003,seed:1701,truth:0,selected:null,revealed:false,hinted:false,run:0};
const descriptions=['확산으로 사라진 무늬를 복원하고, 단서와 일치하는 원본을 찾아보세요.','두 원본이 거의 같은 흔적을 남겼습니다. 지금 가진 단서로 구분할 수 있을까요?','더 작은 구조가 숨어 있습니다. 무엇을 복원할 수 있고 무엇은 추측일까요?'];
let cs,y,restored,animation=null;
const color={teal:'#258276',slate:'#aeb8c3',orange:'#c7805a',grid:'#edf0f3',text:'#9ca7b1'};
function fmt(n){return n===0?'0':Math.abs(n)>=1e4?n.toExponential(1):Math.abs(n)<.001?n.toExponential(1):n.toFixed(3);}
function line(points,x,y){return points.map((v,i)=>(i?'L':'M')+x(i).toFixed(2)+','+y(v).toFixed(2)).join(' ');}
function stop(){if(animation!==null)cancelAnimationFrame(animation);animation=null;$('animate').textContent='▷ 되감기 재생';}
function buildObservation(){cs=M.candidates(state.level);y=M.observe(cs[state.truth],state.T,state.eps,state.seed);}
function reset(level=state.level){stop();state.level=level;state.T=[.025,.075,.065][level];state.eps=.003;state.seed=1701+level*911;state.truth=[0,1,0][level];state.selected=null;state.revealed=false;state.hinted=false;state.method='tikhonov';$('rewind').value=100;$('cutoff').value=12;$('regularization').value=-3;$('diffusion').value=state.T;$('noise').value=state.eps;$('feedback').hidden=true;$('hint').disabled=false;$('hint').textContent='＋ 더 이른 시점의 단서';buildObservation();drawCandidates();render();}
function plot(){const w=matchMedia('(max-width:760px)').matches?400:760,h=260,l=43,r=17,top=19,bottom=37,n=256;const obs=M.sample(y,n),rec=M.sample(restored,n),truth=M.sample(cs[state.truth],n),show=state.revealed||state.tab==='lab';let min=Math.min(0,...obs,...rec),max=Math.max(1.7,...obs,...rec);if(show){min=Math.min(min,...truth);max=Math.max(max,...truth);}const padding=(max-min)*.08;min-=padding;max+=padding;const X=i=>l+i/(n-1)*(w-l-r),Y=v=>top+(max-v)/(max-min)*(h-top-bottom);let svg='';for(let j=0;j<=4;j++){const v=min+(max-min)*j/4;svg+=`<line x1="${l}" y1="${Y(v)}" x2="${w-r}" y2="${Y(v)}" stroke="${color.grid}"/><text x="${l-9}" y="${Y(v)+3}" text-anchor="end" font-size="9" fill="${color.text}">${Math.abs(v)>1e4?v.toExponential(0):v.toFixed(1)}</text>`;}if(min<0)svg+=`<line x1="${l}" x2="${w-r}" y1="${Y(0)}" y2="${Y(0)}" stroke="#d7b6a7" stroke-dasharray="4 4"/>`;for(let j=0;j<=4;j++)svg+=`<text x="${l+(w-l-r)*j/4}" y="${h-14}" text-anchor="middle" font-size="9" fill="${color.text}">${['0','π/2','π','3π/2','2π'][j]}</text>`;svg+=`<text x="${l}" y="10" font-size="8" fill="${color.text}">p(θ)</text><text x="${w-r}" y="${h-14}" dx="13" font-size="9" fill="${color.text}">θ</text>`;
svg+=`<path d="${line(obs,X,Y)}" fill="none" stroke="${color.slate}" stroke-width="1.7"/>`;if(show)svg+=`<path d="${line(truth,X,Y)}" fill="none" stroke="${color.orange}" stroke-width="1.8" stroke-dasharray="5 4"/>`;svg+=`<path d="${line(rec,X,Y)}" fill="none" stroke="${color.teal}" stroke-width="2.2" stroke-linejoin="round"/>`;$('signal').setAttribute('viewBox',`0 0 ${w} ${h}`);$('signal').innerHTML=svg;$('truth-legend').hidden=!show;
}
function ring(id,c,teal){let svg='';for(let i=0;i<100;i++){const a=i/100*TAU-Math.PI/2,b=(i+.95)/100*TAU-Math.PI/2,v=M.value(c,TAU*i/100),opacity=Math.max(.08,Math.min(1,v/1.7));svg+=`<path d="M${50+35*Math.cos(a)},${50+35*Math.sin(a)} A35 35 0 0 1 ${50+35*Math.cos(b)},${50+35*Math.sin(b)}" stroke="${v<0?'#c7805a':teal?color.teal:'#8798aa'}" stroke-opacity="${v<0?1:opacity}" stroke-width="12" fill="none"/>`;}svg+=`<circle cx="50" cy="50" r="20" fill="none" stroke="#eef1f4" stroke-dasharray="1 4"/><circle cx="50" cy="50" r="2" fill="#d0d9df"/>`;$(id).innerHTML=svg;}
function spectrum(){const W=1120,H=200,l=38,r=15,t=15,b=30,low=-5;let high=Math.max(0,Math.ceil(Math.log10(Math.max(...restored.a.map(Math.abs),...restored.b.map(Math.abs),1))));const X=k=>l+(k-.5)/24*(W-l-r),Y=v=>t+(high-Math.max(low,Math.log10(Math.max(v,1e-5))))/(high-low)*(H-t-b),base=H-b;let svg='';for(let pow=low;pow<=high;pow++){const yy=Y(10**pow);svg+=`<line x1="${l}" y1="${yy}" x2="${W-r}" y2="${yy}" stroke="${color.grid}"/><text x="${l-7}" y="${yy+3}" text-anchor="end" font-size="8" fill="${color.text}">10${['⁻⁵','⁻⁴','⁻³','⁻²','⁻¹','⁰','¹','²','³','⁴','⁵','⁶','⁷','⁸','⁹','¹⁰','¹¹','¹²','¹³','¹⁴','¹⁵','¹⁶','¹⁷','¹⁸','¹⁹','²⁰','²¹','²²','²³','²⁴','²⁵','²⁶','²⁷','²⁸','²⁹','³⁰'][pow+5]||'^'+pow}</text>`;}const cutoff=+$('cutoff').value;for(let k=1;k<=24;k++){const a=Math.hypot(y.a[k],y.b[k]),v=Math.hypot(restored.a[k],restored.b[k]),xx=X(k);if(k>cutoff)svg+=`<rect x="${xx-20}" y="${t}" width="40" height="${base-t}" fill="#f7f8fa"/>`;svg+=`<rect x="${xx-8}" y="${Y(a)}" width="6" height="${Math.max(0,base-Y(a))}" rx="1.4" fill="${color.slate}"><title>k=${k} 관측: ${a.toExponential(3)}</title></rect><rect x="${xx+2}" y="${Y(v)}" width="6" height="${Math.max(0,base-Y(v))}" rx="1.4" fill="${color.teal}"><title>k=${k} 복원: ${v.toExponential(3)}</title></rect><text x="${xx}" y="${H-12}" text-anchor="middle" font-size="9" fill="${color.text}">${k}</text>`;}if(state.eps>0){const yy=Y(Math.SQRT2*state.eps);svg+=`<line x1="${l}" x2="${W-r}" y1="${yy}" y2="${yy}" stroke="#c59574" stroke-width="1" stroke-dasharray="4 4"/>`;}$('spectrum').innerHTML=svg;}
function drawCandidates(){const labels=['후보 A','후보 B','후보 C'];$('candidates').innerHTML=cs.map((c,j)=>{const s=M.sample(c,128),d=line(s,i=>i/127*200,v=>45-(v-.4)*32);return `<button class="candidate" data-choice="${j}" aria-pressed="false"><span>${labels[j]}</span><i class="radio"></i><svg viewBox="0 0 200 52" aria-label="${labels[j]} 원본 밀도"><path d="${d}" fill="none" stroke="#90a49f" stroke-width="1.5"/></svg></button>`;}).join('')+'<button class="candidate" data-choice="3" aria-pressed="false"><span>판단 보류</span><i class="radio"></i><div class="unknown">?</div><p>현재 단서로는 구분 불가</p></button>';
$('candidates').querySelectorAll('button').forEach(el=>el.addEventListener('click',()=>{state.selected=+el.dataset.choice;$('candidates').querySelectorAll('button').forEach(b=>{const on=b===el;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);});$('selection-label').textContent=state.selected===3?'복수의 후보가 관측과 양립한다고 판단했습니다.':`${labels[state.selected]}를 선택했습니다.`;$('submit').disabled=false;}));$('submit').disabled=true;$('selection-label').textContent='후보를 선택한 뒤 판단을 확인하세요.';
}
function render(){const tau=state.T*(+$('rewind').value/100),cutoff=+$('cutoff').value,lambda=10**+$('regularization').value;restored=M.restore(y,tau,cutoff,lambda,state.method);$('rewind-value').textContent=`${$('rewind').value}%`;$('cutoff-value').textContent=`k ≤ ${cutoff}`;$('lambda-value').textContent=lambda.toExponential(1);$('diffusion-value').textContent=state.T.toFixed(3);$('noise-value').textContent=state.eps.toFixed(4);$('metric-time').textContent=state.T.toFixed(3);$('metric-noise').textContent=state.eps.toFixed(4);let gain=0;for(let k=1;k<=cutoff;k++){const h=Math.exp(-k*k*tau);gain=Math.max(gain,state.method==='tikhonov'?h/(h*h+lambda):1/h);}$('metric-gain').textContent=fmt(gain)+'×';const show=state.revealed||state.tab==='lab',min=Math.min(...M.sample(restored,512));$('error-label').textContent=show?'원본과의 L² 오차':'최소 복원 밀도';$('metric-error').textContent=show?fmt(M.error(restored,cs[state.truth])):fmt(min);$('metric-error').classList.toggle('danger',!show&&min<0);$('lambda-control').style.opacity=state.method==='tikhonov'?'1':'.35';$('regularization').disabled=state.method!=='tikhonov';$('method-help').textContent=state.method==='tikhonov'?'약한 주파수의 과도한 증폭을 억제합니다.':'주파수 제한 이내의 모드를 그대로 역산합니다.';$('insight').textContent=min<0?'복원 밀도가 음수가 되었습니다. 되감기를 줄이거나, 주파수 제한·정규화를 조절해 보세요.':gain>40?'작은 관측 오차가 크게 증폭됩니다. 선명한 무늬가 반드시 원본의 흔적은 아닙니다.':cutoff<6?'큰 윤곽은 남지만 작은 구조는 버려집니다. 주파수 제한을 올려 변화를 비교해 보세요.':'안정적인 복원과 디테일 사이의 균형을 찾아보세요. 감쇠된 성분이 오차보다 작은지도 확인하세요.';$('mission-text').textContent=state.tab==='lab'?'원본을 보며 확산 시간과 측정 오차를 바꿔 보세요. 같은 오차 실현을 유지해 조건 간 비교가 가능합니다.':descriptions[state.level];$('mission-label').textContent=state.tab==='lab'?'FREE EXPLORATION':'YOUR MISSION';$('case-count').textContent=`CASE 0${state.level+1} / 03`;document.querySelectorAll('.case').forEach(b=>b.classList.toggle('active',+b.dataset.level===state.level));document.querySelectorAll('[data-method]').forEach(b=>{const on=b.dataset.method===state.method;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});plot();ring('ring-observed',y,false);ring('ring-restored',restored,true);spectrum();}
function tab(name){if(name==='theory'){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));$('theory').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}stop();state.tab=name;document.querySelectorAll('.nav').forEach(b=>{const on=b.dataset.tab===name;b.classList.toggle('active',on);b.setAttribute('aria-current',on?'page':'false');});$('lab-controls').hidden=name!=='lab';$('answer-section').hidden=name==='lab';$('lab-note').hidden=name!=='lab';if(name==='puzzle')reset();else render();}
document.querySelectorAll('.case').forEach(el=>el.addEventListener('click',()=>reset(+el.dataset.level)));
document.querySelectorAll('.nav').forEach(el=>el.addEventListener('click',()=>tab(el.dataset.tab)));
document.querySelectorAll('[data-method]').forEach(el=>el.addEventListener('click',()=>{state.method=el.dataset.method;render();}));
['rewind','cutoff','regularization'].forEach(id=>$(id).addEventListener('input',()=>{stop();render();}));
$('reset').addEventListener('click',()=>reset());
['diffusion','noise'].forEach(id=>$(id).addEventListener('input',()=>{stop();state.T=+$('diffusion').value;state.eps=+$('noise').value;buildObservation();render();}));
$('resample').addEventListener('click',()=>{state.seed+=71;buildObservation();render();});
$('hint').addEventListener('click',()=>{stop();state.T*=.3;state.seed+=101;state.hinted=true;state.revealed=false;state.selected=null;$('feedback').hidden=true;$('diffusion').value=state.T;$('hint').disabled=true;$('hint').textContent='✓ 더 이른 관측으로 교체됨';buildObservation();drawCandidates();render();});
$('submit').addEventListener('click',()=>{if(state.selected===null)return;const feasible=M.compatible(y,cs,state.T,state.eps),answer=feasible.length>1?3:feasible[0],ok=state.selected===answer;state.revealed=true;const names=feasible.map(i=>'ABC'[i]).join(', ');$('feedback').hidden=false;$('feedback').classList.toggle('wrong',!ok);$('feedback').innerHTML=`<strong>${ok?'좋은 판단입니다.':'관측과 양립하는 후보를 다시 살펴보세요.'}</strong>${feasible.length>1?`후보 ${names}는 모두 각 Fourier 계수의 오차 한계 ε 안에서 관측을 설명합니다. 현재 조건에서 단일 원본은 식별되지 않습니다.`:`후보 ${names}만 모든 계수의 오차 한계를 만족합니다. 나머지 후보는 적어도 한 계수에서 ε를 초과합니다.`} 실제 생성에 사용한 원본은 ${'ABC'[state.truth]}입니다. 이제 점선 원본과 복원 오차를 비교할 수 있습니다.${state.hinted?' 더 이른 시점의 관측을 사용한 결과입니다.':''}`;render();});
$('animate').addEventListener('click',()=>{if(animation!==null){stop();return;}const begin=performance.now();$('animate').textContent='Ⅱ 재생 멈추기';function tick(now){$('rewind').value=Math.min(100,(now-begin)/35);render();if(now-begin<3500)animation=requestAnimationFrame(tick);else stop();}animation=requestAnimationFrame(tick);});
const wave=Array.from({length:240},(_,i)=>{const x=i/239*350,amp=7+23*i/239,yy=65+amp*Math.sin(i/239*27)+6*Math.sin(i/239*51);return `${i?'L':'M'}${x.toFixed(2)},${yy.toFixed(2)}`;}).join(' ');$('hero-wave').setAttribute('d',wave);
reset();

window.addEventListener('resize',()=>{plot();});
